reference_solution:
def removeNthFromEnd(head, n):
    dummy = ListNode(0, head)
    fast = slow = dummy
    for _ in range(n):
        fast = fast.next
    while fast.next:
        fast = fast.next
        slow = slow.next
    slow.next = slow.next.next
    return dummy.next

brute_force_solution:
def removeNthFromEnd(head, n):
    vals = []
    while head:
        vals.append(head.val)
        head = head.next
    del vals[len(vals) - n]
    out = None
    for v in reversed(vals):
        out = ListNode(v, out)
    return out

